constexpr PhysicalIdMetadataKeyInfo const* find_physical_id_metadata_key(
   std::string_view name
) noexcept
{
   for (auto const& info : PhysicalIdMetadataKeyCatalog) {
      if (info.name == name) {
         return &info;
      }
   }
   return nullptr;
}

constexpr bool physical_id_dynamic_key_matches(
   PhysicalIdDynamicKeyInfo const& info,
   std::string_view name
) noexcept
{
   if (name.size() < info.prefix.size() + info.suffix.size()
       || name.substr(0, info.prefix.size()) != info.prefix
       || name.substr(name.size() - info.suffix.size()) != info.suffix) {
      return false;
   }
   const std::string_view indices = name.substr(
      info.prefix.size(),
      name.size() - info.prefix.size() - info.suffix.size()
   );
   if (indices.empty()) {
      return false;
   }
   int count = 1;
   bool need_digit = true;
   for (char value : indices) {
      if (value == '_') {
         if (need_digit) {
            return false;
         }
         ++count;
         need_digit = true;
      } else if (value < '0' || value > '9') {
         return false;
      } else {
         need_digit = false;
      }
   }
   return !need_digit && count == info.index_count;
}

constexpr PhysicalIdDynamicKeyInfo const* find_physical_id_dynamic_key(
   std::string_view name
) noexcept
{
   for (auto const& info : PhysicalIdDynamicKeyCatalog) {
      if (physical_id_dynamic_key_matches(info, name)) {
         return &info;
      }
   }
   return nullptr;
}

